cat > test_reproduction.js << 'EOF'
import { parseEuros } from './src/money.js';
import { validate } from './src/store.js';

// Test the bug: 39.95 should parse to 3995 cents, not 3995.0000000000005
const price = parseEuros('39.95');
console.log('parseEuros("39.95") =', price);
console.log('Is it an integer?', Number.isInteger(price));

// Try to create a subscription with this price
const sub = { name: 'Gym', price, cycle: 'month', since: '2026-10-03' };
const problem = validate(sub);
if (problem) {
  console.log('Validation fails:', problem);
} else {
  console.log('Validation passes!');
}
EOF
node test_reproduction.js
